class ImmutableColor {
    private final int r, g, b;
    ImmutableColor(int r, int g, int b) { this.r = r; this.g = g; this.b = b; }
    int getRed() { return r; }
    int getGreen() { return g; }
    int getBlue() { return b; }
}

ImmutableColor c = new ImmutableColor(255, 0, 0);
System.out.println(c.getRed() + ", " + c.getGreen() + ", " + c.getBlue());

// void setRed(int r) { this.r = r; } // ZLAMALOBY niezmiennosc
// Dodanie tej metody natychmiast lamie niemutowalnosc, bo pozwala zmienic wartosc pola
// PO utworzeniu obiektu - a definicja niezmiennosci mowi wprost, ze CALY stan obiektu musi
// byc identyczny przez caly czas jego zycia. Nawet jesli reszta klasy (final pola, brak innych
// setterow) wyglada poprawnie, JEDEN setter wystarczy, zeby klasa przestala byc niemutowalna.

final class ImmutableMoney2 {
    private final java.math.BigDecimal amount;
    private final String currency;
    ImmutableMoney2(java.math.BigDecimal amount, String currency) { this.amount = amount; this.currency = currency; }
    ImmutableMoney2 add(java.math.BigDecimal ile) {
        return new ImmutableMoney2(this.amount.add(ile), this.currency);
    }
    public String toString() { return amount + " " + currency; }
}

ImmutableMoney2 m = new ImmutableMoney2(new java.math.BigDecimal("10.00"), "PLN");
ImmutableMoney2 m2 = m.add(new java.math.BigDecimal("5.00"));
System.out.println(m);  // 10.00 PLN - bez zmian
System.out.println(m2); // 15.00 PLN - nowy obiekt

// 'Pole final' oznacza jedynie, ze REFERENCJI przechowywanej w tym polu nie da sie ponownie
// przypisac (this.pole = nowaWartosc; jest zabronione poza konstruktorem). Nie mowi to NIC
// o tym, czy OBIEKT, na ktory ta referencja wskazuje, moze sam w sobie zmienic swoj stan.
// 'Obiekt niemutowalny' to znacznie silniejsza gwarancja - CALY jego widoczny stan (wlacznie
// z zawartoscia obiektow wskazywanych przez jego pola) musi byc identyczny przez cale zycie.
// Klasa z final polem typu List<String> jest przykladem, gdzie final field != immutable object -
// referencja jest 'przybita', ale zawartosc listy nadal mozna zmieniac.

record Punkt3D(double x, double y, double z) {}

Punkt3D punkt = new Punkt3D(1, 2, 3);
System.out.println(punkt);
// punkt.x = 10; // BLAD KOMPILACJI: x nie jest publicznym polem
// Rekord generuje PRYWATNE, final pola i PUBLICZNE metody akcesorow o nazwie skladowej
// (x(), y(), z()) - nie istnieje zadna skladnia 'punkt.x = ...', bo x NIE JEST publicznym
// polem, tylko wewnetrznym szczegolem implementacji dostepnym wylacznie przez metode x().

class BrokenBox {
    private final int[] dane;
    BrokenBox(int[] dane) { this.dane = dane; }
    int[] getDane() { return dane; }
}

BrokenBox box = new BrokenBox(new int[]{1, 2, 3});
box.getDane()[0] = 999;
System.out.println(java.util.Arrays.toString(box.getDane())); // [999, 2, 3]

int[] oryginal = {10, 20, 30};
BrokenBox box = new BrokenBox(oryginal);
oryginal[0] = -1; // mutacja PO utworzeniu obiektu, bez zadnego settera
System.out.println(java.util.Arrays.toString(box.getDane())); // [-1, 20, 30] - przecieklo!

// NIEMUTOWALNE typy z JDK:
// 1. String - kazda 'zmiana' zwraca NOWY String
// 2. Integer (i pozostale wrappery: Long, Double, Boolean...) - raz utworzony, niezmienny
// 3. java.time.LocalDate/LocalDateTime/Instant - CALE java.time jest niemutowalne
// 4. java.math.BigDecimal/BigInteger - operacje zwracaja nowe instancje
//
// MUTOWALNE typy (mimo pozornej prostoty):
// 1. StringBuilder - append/insert/delete MODYFIKUJA ten sam obiekt
// 2. java.util.ArrayList (i wiekszosc kolekcji) - add/remove/set mutuja w miejscu
// 3. java.util.Date - setTime() zmienia stan istniejacego obiektu (dlatego java.time.* go zastapilo)

final class ImmutableUser {
    private final String login;
    private final String email;
    ImmutableUser(String login, String email) { this.login = login; this.email = email; }
    String getLogin() { return login; }
    String getEmail() { return email; }
}
// final na klasie zabrania dziedziczenia po niej - bez tego, podklasa moglaby DODAC WLASNE,
// MUTOWALNE pole (lamiac obietnice niemutowalnosci calej hierarchii) albo PRZESLONIC metode
// (np. getLogin()) tak, by zwracala rozne wartosci przy kolejnych wywolaniach - final klasa
// gwarantuje, ze KAZDY obiekt typu ImmutableUser (nie tylko instancje bazowej klasy) jest
// faktycznie niemutowalny.

// Problemy watkowe (race conditions, niespojne odczyty) powstaja, gdy WIELE watkow moze
// jednoczesnie CZYTAC i PISAC ten sam, wspoldzielony stan bez synchronizacji. Obiekt
// niemutowalny CALKOWICIE eliminuje mozliwosc pisania po utworzeniu - kazdy watek widzi
// DOKLADNIE ten sam, niezmienny stan od momentu zakonczenia konstruktora, wiec nie ma
// zadnej sytuacji 'watek A zmienia, watek B czyta w polowie zmiany'. Dlatego wiele watkow
// moze bezpiecznie CZYTAC ten sam obiekt niemutowalny rownolegle, bez zadnej synchronizacji
// (locks, synchronized, volatile) - dokladnie ten sam wniosek co w Lesson10_ThreadSafety.

class ImmutableInterval {
    private final int start, end;
    ImmutableInterval(int start, int end) {
        if (start > end) throw new IllegalArgumentException("start > end");
        this.start = start;
        this.end = end;
    }
}

ImmutableInterval ok = new ImmutableInterval(1, 10);
try {
    ImmutableInterval bledny = new ImmutableInterval(10, 1);
} catch (IllegalArgumentException e) {
    System.out.println("Blad: " + e.getMessage());
}

record Zespol(String nazwa, java.util.List<String> czlonkowie) {}

java.util.List<String> lista = new java.util.ArrayList<>(java.util.List.of("Ala", "Piotr"));
Zespol zespol = new Zespol("Backend", lista);
lista.add("Intruz");
System.out.println(zespol); // 'Intruz' widoczny w zespol.czlonkowie() mimo ze to rekord!

// CHECKLISTA "czy klasa jest naprawde niemutowalna":
// 1. Czy WSZYSTKIE pola sa 'private final'?
// 2. Czy klasa jest oznaczona jako 'final' (blokuje mutowalne podklasy)?
// 3. Czy klasa NIE MA zadnych setterow ani innych metod mutujacych pola?
// 4. Czy wartosci pol sa przypisywane WYLACZNIE w konstruktorze?
// 5. Czy KAZDE pole typu mutowalnego (tablica, kolekcja, Date, wlasna klasa z setterami)
//    jest DEFENSYWNIE KOPIOWANE zarowno w konstruktorze, JAK I w getterze?
// 6. (bonus) Czy konstruktor waliduje inwarianty (np. zakresy, null-checki)?

class Address {
    private String miasto;
    Address(String miasto) { this.miasto = miasto; }
    String getMiasto() { return miasto; }
    void setMiasto(String miasto) { this.miasto = miasto; }
}

class ImmutableEmployee {
    private final Address adres;
    ImmutableEmployee(Address adres) { this.adres = adres; }
    Address getAdres() { return adres; }
}

ImmutableEmployee pracownik = new ImmutableEmployee(new Address("Warszawa"));
pracownik.getAdres().setMiasto("Krakow"); // BEZ zadnego settera na ImmutableEmployee!
System.out.println(pracownik.getAdres().getMiasto()); // Krakow

// Klasa ImmutablePoint z Lesson10_FinalKeyword (private final int x, y) oraz ImmutableColor
// z Zadania 1 tej lekcji (private final int r, g, b) sa STRUKTURALNIE IDENTYCZNE - obie maja
// TYLKO pola typu prymitywnego, wiec 'przepis' final + brak setterow w PELNI wystarcza dla
// obu, bez zadnej dodatkowej pracy.
// Tamten przyklad NIE POKAZYWAL kluczowej pulapki tej lekcji: co sie dzieje, gdy pole jest
// typu MUTOWALNEGO (tablica, List, Date, wlasna klasa z setterami) - wtedy samo final NIE
// WYSTARCZA i potrzebna jest dodatkowa, DEFENSYWNA KOPIA (temat nastepnej lekcji, Lesson25).

class Rejestracja {
    private final java.util.Date utworzono;
    Rejestracja(java.util.Date utworzono) { this.utworzono = utworzono; }
    java.util.Date getUtworzono() { return utworzono; }
}

java.util.Date data = new java.util.Date(0L);
Rejestracja r = new Rejestracja(data);
data.setTime(1_000_000_000_000L);
System.out.println(r.getUtworzono()); // zmieniona data, mimo final pola!

class ImmutableConfig {
    private final java.util.Map<String, String> ustawienia;
    ImmutableConfig(java.util.Map<String, String> ustawienia) { this.ustawienia = ustawienia; }
    java.util.Map<String, String> getUstawienia() { return ustawienia; }
}

java.util.Map<String, String> mapa = new java.util.HashMap<>();
mapa.put("tryb", "produkcja");
ImmutableConfig config = new ImmutableConfig(mapa);
mapa.put("tajny_klucz", "12345"); // wstrzykniete z zewnatrz!
System.out.println(config.getUstawienia()); // zawiera tajny_klucz mimo final pola

// Scenariusz: cache przechowuje wspoldzielony obiekt Config pod kluczem "aktualny". Watek A
// pobiera go z cache, myslac ze modyfikuje SWOJA lokalna kopie (np. dopisuje ustawienie), ale
// jesli Config jest MUTOWALNY, tak naprawde zmienia WSPOLNY obiekt widoczny przez WSZYSTKIE
// inne watki. Watek B, ktory rowniez pobiera 'aktualny' z tego samego cache, dostaje NAGLE
// zmieniony stan, ktorego sie nie spodziewal - klasyczny, trudny do zdiagnozowania blad
// wspoldzielonego mutowalnego stanu.
// Z obiektem NIEMUTOWALNYM ten problem znika CALKOWICIE - kazdy watek dostaje z cache
// DOKLADNIE ten sam, gwarantowanie niezmienny stan, wiec mozna go bezpiecznie wspoldzielic
// bez ryzyka, ze ktos 'po cichu' zepsuje to, co widzi ktos inny.

final class ImmutablePair<K, V> {
    private final K key;
    private final V value;
    ImmutablePair(K key, V value) { this.key = key; this.value = value; }
    K getKey() { return key; }
    V getValue() { return value; }
}

ImmutablePair<String, Integer> p1 = new ImmutablePair<>("wiek", 30);
System.out.println(p1.getKey() + "=" + p1.getValue());

ImmutablePair<Integer, java.util.List<String>> p2 = new ImmutablePair<>(1, new java.util.ArrayList<>(java.util.List.of("a")));
p2.getValue().add("b"); // ZMIENIA zawartosc V, mimo ze para sama w sobie jest 'niemutowalna'
System.out.println(p2.getValue());
// Sama para ImmutablePair jest niemutowalna dla WLASNEGO stanu (key/value nie da sie
// podmienic), ale NIE gwarantuje niczego o mutowalnosci SAMEGO typu V - jesli V jest
// mutowalne, ta pulapka wciaz obowiazuje.

final class ImmutableCounter {
    private final int value;
    ImmutableCounter(int value) { this.value = value; }
    int getValue() { return value; }
    ImmutableCounter incremented() { return new ImmutableCounter(value + 1); }
}

ImmutableCounter c = new ImmutableCounter(0);
ImmutableCounter c5 = c.incremented().incremented().incremented().incremented().incremented();
System.out.println("c: " + c.getValue());   // 0 - bez zmian
System.out.println("c5: " + c5.getValue()); // 5

class ImmutableOrder {
    private final String id;
    private final java.util.List<String> items;
    private final java.math.BigDecimal total;
    ImmutableOrder(String id, java.util.List<String> items, java.math.BigDecimal total) {
        this.id = id; this.items = items; this.total = total;
    }
    java.util.List<String> getItems() { return items; }
}

java.util.List<String> lista = new java.util.ArrayList<>(java.util.List.of("Laptop"));
ImmutableOrder order = new ImmutableOrder("O1", lista, new java.math.BigDecimal("3500"));

lista.add("Mysz"); // (a) mutacja oryginalnej referencji
System.out.println(order.getItems());

order.getItems().add("Klawiatura"); // (b) mutacja przez getter
System.out.println(order.getItems());
// Obie pulapki zostana naprawione DEFENSYWNYM KOPIOWANIEM w Lesson25_DefensiveCopying.

// Mimo nazw sugerujacych mutacje (replace, toUpperCase, substring 'brzmi' jak operacje
// zmieniajace String), KAZDA z tych metod ZWRACA NOWY obiekt String, a oryginalny obiekt,
// na ktorym je wywolano, pozostaje NIEZMIENIONY. String s1 = "abc"; String s2 = s1.toUpperCase();
// - s1 nadal jest "abc", s2 to zupelnie NOWY obiekt "ABC". Klasyczna pulapka poczatkujacych
// to zapomnienie o przypisaniu wyniku ('s1.toUpperCase();' bez uzycia wyniku nic nie zmienia
// w s1). To dokladnie ta zasada 'zmiana = nowy obiekt' opisana w teorii tej lekcji.

interface Ksztalt { double pole(); }
record Kolo(double r) implements Ksztalt { public double pole() { return Math.PI * r * r; } }
record Prostokat(double w, double h) implements Ksztalt { public double pole() { return w * h; } }

Ksztalt[] ksztalty = { new Kolo(2), new Prostokat(3, 4) };
Runnable task = () -> {
    for (Ksztalt k : ksztalty) System.out.println(Thread.currentThread().getName() + ": " + k.pole());
};
Thread t1 = new Thread(task);
Thread t2 = new Thread(task);
t1.start(); t2.start();
try { t1.join(); t2.join(); } catch (InterruptedException e) {}
// Zero synchronizacji potrzebne - Kolo/Prostokat sa w pelni niemutowalne, wiec rownoczesny
// odczyt z wielu watkow jest zawsze bezpieczny.

final class ImmutableAudytLog {
    private final java.util.List<String> wpisy;
    ImmutableAudytLog(java.util.List<String> wpisy) { this.wpisy = wpisy; }
    ImmutableAudytLog withEntry(String wpis) {
        java.util.List<String> nowe = new java.util.ArrayList<>(wpisy);
        nowe.add(wpis);
        return new ImmutableAudytLog(nowe);
    }
    public String toString() { return wpisy.toString(); }
}

ImmutableAudytLog log0 = new ImmutableAudytLog(new java.util.ArrayList<>());
ImmutableAudytLog log1 = log0.withEntry("start");
ImmutableAudytLog log2 = log1.withEntry("przetwarzanie");
ImmutableAudytLog log3 = log2.withEntry("koniec");
System.out.println(log0);
System.out.println(log1);
System.out.println(log2);
System.out.println(log3);

record Wspolrzedne(int x, int y) {}

java.util.Map<Wspolrzedne, String> mapa = new java.util.HashMap<>();
mapa.put(new Wspolrzedne(1, 2), "Punkt A");
System.out.println(mapa.get(new Wspolrzedne(1, 2))); // "Punkt A" - odnaleziono poprawnie!
// Rekord ma AUTOMATYCZNIE wygenerowany equals()/hashCode() oparty na WARTOSCIACH pol - dwa
// rekordy Wspolrzedne(1,2) sa sobie rowne i maja IDENTYCZNY hashCode. Poniewaz rekord jest
// niemutowalny, ten hashCode NIGDY sie nie zmieni po dodaniu do mapy. Gdyby uzyc MUTOWALNEGO
// obiektu jako klucza i zmienic jego pola PO dodaniu do HashMap, hashCode() zwrocilby inna
// wartosc niz ta, pod ktora obiekt zostal faktycznie zaindeksowany w tablicy hashujacej -
// wpis staje sie 'nieodnajdywalny' (map.get(...) zwroci null, mimo ze wpis fizycznie tam jest).

class ImmutableMatrix {
    private final int[][] dane;
    ImmutableMatrix(int[][] dane) { this.dane = dane; }
    int[][] getDane() { return dane; }
}

ImmutableMatrix matrix = new ImmutableMatrix(new int[][]{{1, 2}, {3, 4}});
matrix.getDane()[0][0] = 999;
System.out.println(java.util.Arrays.deepToString(matrix.getDane())); // [[999, 2], [3, 4]]

final class ImmutableRange {
    private final int min, max;
    ImmutableRange(int min, int max) { this.min = min; this.max = max; }
    boolean contains(int value) { return value >= min && value <= max; }
    ImmutableRange intersect(ImmutableRange other) {
        int newMin = Math.max(min, other.min);
        int newMax = Math.min(max, other.max);
        if (newMin > newMax) return null;
        return new ImmutableRange(newMin, newMax);
    }
    public String toString() { return "[" + min + ", " + max + "]"; }
}

ImmutableRange r1 = new ImmutableRange(1, 10);
ImmutableRange r2 = new ImmutableRange(5, 15);
System.out.println(r1.intersect(r2)); // [5, 10]

ImmutableRange r3 = new ImmutableRange(20, 30);
System.out.println(r1.intersect(r3)); // null

final class ImmutableSnapshot<T> {
    private final T value;
    ImmutableSnapshot(T value) { this.value = value; }
    T getValue() { return value; }
}

ImmutableSnapshot<String> s1 = new ImmutableSnapshot<>("bezpieczne");
System.out.println(s1.getValue());

class Mutowalna { int licznik = 0; }
ImmutableSnapshot<Mutowalna> s2 = new ImmutableSnapshot<>(new Mutowalna());
s2.getValue().licznik = 99; // NIEBEZPIECZNE - zmienia stan wewnetrzny mimo braku settera
System.out.println(s2.getValue().licznik);
// Ograniczenie: ImmutableSnapshot<T> gwarantuje TYLKO, ze referencja do T nie zostanie
// podmieniona - jesli T samo jest mutowalne, jego WEWNETRZNY stan nadal mozna zmienic.

// Styl niemutowalny (new ImmutableCounter(value+1) w kazdej iteracji 1_000_000 razy) tworzy
// milion malych, krotko zyjacych obiektow. Nowoczesny generacyjny Garbage Collector (patrz
// _15_jvm_internals) jest ZAPROJEKTOWANY do tanie'go zbierania wlasnie takich, efemerycznych
// obiektow (Eden space) - dla PROSTYCH obiektow jak ImmutableCounter narzut jest zazwyczaj
// POMIJALNY w praktyce, tym bardziej ze JIT (escape analysis) czasem w ogole unika alokacji
// na stercie.
// Koszt STAJE SIE realnym problemem, gdy: (a) obiekty sa DUZE/skomplikowane do skonstruowania
// (np. defensywne kopiowanie dlugich list przy KAZDEJ zmianie), (b) petla jest EKSTREMALNIE
// czesto wykonywana (miliardy iteracji w hot path) - wtedy mutowalny 'akumulator' (jak
// StringBuilder zamiast konkatenacji String) bywa uzasadniony wyjatkiem od reguly.

class BankAccountSnapshot {
    private final String numerKonta;
    private final java.math.BigDecimal saldo;
    private final java.util.List<String> ostatnieTransakcje;
    BankAccountSnapshot(String numerKonta, java.math.BigDecimal saldo, java.util.List<String> ostatnieTransakcje) {
        this.numerKonta = numerKonta;
        this.saldo = saldo;
        this.ostatnieTransakcje = ostatnieTransakcje; // CELOWO bez kopii
    }
    java.util.List<String> getOstatnieTransakcje() { return ostatnieTransakcje; } // CELOWO bez kopii
}

java.util.List<String> transakcje = new java.util.ArrayList<>(java.util.List.of("wplata 100"));
BankAccountSnapshot snapshot = new BankAccountSnapshot("PL123", new java.math.BigDecimal("1000"), transakcje);
transakcje.add("FALSZYWA transakcja wstrzykniete z zewnatrz");
System.out.println(snapshot.getOstatnieTransakcje()); // pokazuje falszywy wpis!
// Lesson25_DefensiveCopying naprawi ten 'snapshot' przez kopiowanie listy zarowno w
// konstruktorze, jak i w getterze - dopiero wtedy bedzie to NAPRAWDE bezpieczne, niezmienne
// zdjecie stanu konta, ktore mozna bezpiecznie wyslac przez siec lub zapisac w logu.
